import { useBffData, useCurrentPage, usePageFilterStatus } from 'hooks';

export function useInnovationHubPortfolioData() {
  const { currentPage } = useCurrentPage();
  const { isLoading: filtersLoading } = usePageFilterStatus(currentPage);

  return useBffData({
    id: 'innovation_innovation-hub_overview',
    kpiGroup: 'innovation',
    skipRequest: filtersLoading,
  });
}
